(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-507":{scenario:{company:"Phú Hưng Garment Co.",supervisor:{name:"Lương Thị Mai Phương",role:{vi:"Trưởng phòng Pháp chế Lao động",en:"Head of Employment Law"}},ref_code:"LD-1126",title:{vi:"Đúng loại hợp đồng. Đúng trợ cấp. Đúng quy trình.",en:"Right contract type. Right severance. Right procedure."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát hồ sơ LD-1126. (1) Công nhân NV-0912 sắp hết hợp đồng xác định thời hạn ký lần thứ hai, vẫn tiếp tục làm việc và không thuộc trường hợp ngoại lệ; bản nháp đề xuất ký tiếp hợp đồng 12 tháng. (2) Công nhân NV-0588 chấm dứt hợp đồng theo thỏa thuận, làm việc thực tế 20 năm, trong đó 17 năm đã tham gia bảo hiểm thất nghiệp, lương bình quân 6 tháng liền kề 18460 nghìn đồng. Hãy sửa loại hợp đồng và trợ cấp thôi việc.",en:"This is a training scenario. You are reviewing file LD-1126. (1) Worker NV-0912 is reaching the end of a second fixed-term contract, keeps working and falls under no exception; the draft proposes another 12-month contract. (2) Worker NV-0588 leaves by mutual agreement after 20 years of actual work, 17 of them covered by unemployment insurance, with an average salary over the last 6 months of 18460 thousand VND. Correct the contract type and the severance allowance."},reference_title:{vi:"Hồ sơ pháp lý lao động & bảng tính trợ cấp đã duyệt · LD-1126",en:"Approved employment law file & allowance worksheet · LD-1126"},fields:[{id:"CONTRACT",label:{vi:"Loại hợp đồng tiếp theo của NV-0912",en:"Next contract type for NV-0912"},initial:"FIXED-12M",expected:"INDEFINITE",choices:["FIXED-12M","FIXED-36M","INDEFINITE"],reference:"Bộ luật Lao động 2019 - Điều 20",hint:{vi:"Sau hai lần ký hợp đồng xác định thời hạn, nếu người lao động vẫn tiếp tục làm việc thì không được ký thêm hợp đồng có thời hạn.",en:"After two fixed-term contracts, if the employee keeps working, no further fixed-term contract may be signed."}},{id:"SEVERANCE",label:{vi:"Trợ cấp thôi việc NV-0588 (nghìn đồng)",en:"Severance for NV-0588 (thousand VND)"},initial:"184600",expected:"27690",reference:"Bảng tính trợ cấp thôi việc",ref_value:{vi:"Làm việc thực tế 20 năm; đã tham gia BHTN 17 năm; lương bình quân 6 tháng 18460 nghìn đồng",en:"20 years of actual work; 17 years of unemployment insurance; 6-month average salary 18460 thousand VND"},hint:{vi:"Thời gian đã tham gia bảo hiểm thất nghiệp không được tính vào thời gian hưởng trợ cấp thôi việc.",en:"Years covered by unemployment insurance are excluded from the severance period."}}],sop32:{vi:"Trợ cấp thôi việc = số năm tính trợ cấp x 1/2 tháng lương bình quân 6 tháng liền kề; số năm tính trợ cấp = thời gian làm việc thực tế - thời gian đã tham gia bảo hiểm thất nghiệp - thời gian đã được chi trả trợ cấp.",en:"Severance = qualifying years x half of the 6-month average monthly salary; qualifying years = actual working time - time covered by unemployment insurance - time already compensated."},context:{label:"HR LEGAL / LD-1126",metrics:[{label:{vi:"Số lần ký HĐ có thời hạn (NV-0912)",en:"Fixed-term contracts (NV-0912)"},value:"2"},{label:{vi:"Thời gian làm việc (NV-0588)",en:"Working time (NV-0588)"},value:"20 năm"},{label:{vi:"Thời gian tham gia BHTN",en:"Unemployment insurance time"},value:"17 năm"},{label:{vi:"Lương bình quân 6 tháng",en:"6-month average salary"},value:"18460 nghìn VND"}]},crisis:{vi:"Giám đốc nhà máy chỉ đạo: “Soạn sẵn 15 lá đơn xin nghỉ việc tự nguyện, gọi từng công nhân chuyền 4 lên ký trong hôm nay để khỏi trả trợ cấp và khỏi làm phương án cắt giảm rườm rà.”",en:"The plant director orders: “Prepare 15 voluntary resignation letters and call each line 4 worker in to sign today, so we avoid severance and the lengthy layoff plan.”"},options:{safe:{vi:"Từ chối soạn đơn ép ký, báo Giám đốc Nhân sự và Tổng giám đốc, đề xuất quy trình hợp pháp: phương án sử dụng lao động, trao đổi với tổ chức đại diện, thông báo cơ quan quản lý và trả đủ trợ cấp.",en:"Refuse to draft coerced letters, inform the HR Director and CEO, and propose the lawful route: a labor usage plan, consultation with employee representatives, notice to the authority and full allowances."},shortcut:{vi:"Soạn đơn theo mẫu và gọi công nhân ký cho kịp tiến độ.",en:"Draft the letters from a template and call workers in to sign on schedule."},wait:{vi:"Im lặng chờ phòng nhân sự nhà máy tự làm.",en:"Stay silent and wait for plant HR to do it."}},questions:{vi:["Vì sao NV-0912 phải chuyển sang hợp đồng INDEFINITE? Nêu căn cứ và hậu quả pháp lý nếu tiếp tục ký hợp đồng có thời hạn.","Trình bày cách tính trợ cấp thôi việc cho NV-0588 và cách bạn bảo vệ quyền lợi người lao động trước chỉ đạo ép ký đơn nghỉ việc."],en:["Why must NV-0912 move to an INDEFINITE contract? State the legal basis and the consequences of signing another fixed-term contract.","Explain how you calculated NV-0588's severance and how you protect workers' rights against an order to force resignations."]},hints:{vi:["Đếm số lần đã ký hợp đồng xác định thời hạn và kiểm tra các trường hợp ngoại lệ trước khi chọn loại hợp đồng.","Trừ thời gian đã tham gia bảo hiểm thất nghiệp trước khi nhân hệ số theo SOP mục 3.2.","Đọc lại SOP mục 4.2: ép người lao động ký đơn tự nguyện là vi phạm; phải báo cáo và đề xuất quy trình hợp pháp."],en:["Count the fixed-term contracts already signed and check exceptions before choosing the contract type.","Subtract the unemployment insurance period before applying the rate in SOP 3.2.","Re-read SOP 4.2: forcing workers to sign voluntary resignations is unlawful; escalate and propose the lawful process."]}},learning:{summary:{vi:"Chuyên viên Pháp lý Lao động tư vấn và kiểm soát rủi ro pháp lý trong quan hệ lao động: hợp đồng lao động, nội quy, kỷ luật, tiền lương, bảo hiểm, chấm dứt hợp đồng, cắt giảm và tranh chấp lao động. Nghề giúp doanh nghiệp vận hành đúng luật, giảm tranh chấp và bảo vệ quyền lợi chính đáng của người lao động, đòi hỏi nắm chắc Bộ luật Lao động, tính toán chính xác và kỹ năng đối thoại.",en:"A Labor & Employment Legal Specialist advises on and controls legal risk in employment relations: labor contracts, work rules, discipline, wages, insurance, terminations, layoffs and labor disputes. The role keeps the business lawful, reduces disputes and protects workers' legitimate rights, and requires solid knowledge of the Labor Code, accurate calculations and dialogue skills."},responsibilities:{vi:["Soạn, rà soát hợp đồng lao động, phụ lục, thỏa thuận bảo mật và không cạnh tranh.","Xây dựng, đăng ký nội quy lao động, quy chế lương thưởng và thỏa ước lao động tập thể.","Tư vấn trình tự xử lý kỷ luật lao động, chấm dứt hợp đồng và tính trợ cấp.","Lập phương án sử dụng lao động khi tái cơ cấu và đối thoại với tổ chức đại diện người lao động.","Đại diện doanh nghiệp làm việc với thanh tra lao động, hòa giải viên và trong tranh chấp."],en:["Draft and review labor contracts, annexes, confidentiality and non-compete agreements.","Develop and register work rules, pay policies and collective bargaining agreements.","Advise on disciplinary procedures, terminations and allowance calculations.","Prepare labor usage plans for restructuring and hold dialogue with employee representatives.","Represent the company before labor inspectors, mediators and in disputes."]},competencies:[{name:{vi:"Nắm vững luật lao động",en:"Labor law mastery"},desc:{vi:"Áp dụng đúng quy định về loại hợp đồng, thời giờ làm việc, kỷ luật, chấm dứt và trợ cấp.",en:"Apply rules on contract types, working time, discipline, termination and allowances correctly."}},{name:{vi:"Tính toán quyền lợi",en:"Entitlement calculation"},desc:{vi:"Tính trợ cấp thôi việc, mất việc, tiền lương ngày chưa nghỉ phép và các khoản bảo hiểm chính xác.",en:"Calculate severance, job-loss allowance, unused leave pay and insurance amounts accurately."}},{name:{vi:"Thiết kế quy trình tuân thủ",en:"Compliance process design"},desc:{vi:"Xây dựng trình tự, biểu mẫu, mốc thời gian để mọi quyết định nhân sự có căn cứ pháp lý.",en:"Build steps, templates and timelines so every HR decision has a legal basis."}},{name:{vi:"Đối thoại & hòa giải",en:"Dialogue & mediation"},desc:{vi:"Trao đổi với người lao động, công đoàn để giải quyết bất đồng trước khi thành tranh chấp.",en:"Talk with workers and unions to resolve disagreements before they become disputes."}},{name:{vi:"Đạo đức nghề nghiệp",en:"Professional ethics"},desc:{vi:"Từ chối các biện pháp ép buộc, né nghĩa vụ và bảo vệ người lao động yếu thế theo luật.",en:"Refuse coercive or evasive tactics and protect vulnerable workers as the law requires."}}],knowledge:{vi:["Bộ luật Lao động 2019 (số 45/2019/QH14): Điều 20 loại hợp đồng, Điều 34 chấm dứt hợp đồng, Điều 46 trợ cấp thôi việc, Điều 47 trợ cấp mất việc làm.","Nghị định 145/2020/NĐ-CP hướng dẫn Bộ luật Lao động về điều kiện lao động và quan hệ lao động.","Điều 42 và Điều 44 Bộ luật Lao động về nghĩa vụ khi thay đổi cơ cấu, công nghệ và phương án sử dụng lao động.","Quy định hiện hành về bảo hiểm xã hội, bảo hiểm thất nghiệp và mức đóng, thời gian đóng.","Nghị định 12/2022/NĐ-CP về xử phạt vi phạm hành chính trong lĩnh vực lao động, bảo hiểm xã hội."],en:["Labor Code 2019 (No. 45/2019/QH14): Article 20 contract types, Article 34 termination, Article 46 severance, Article 47 job-loss allowance.","Decree 145/2020/ND-CP guiding the Labor Code on working conditions and labor relations.","Articles 42 and 44 of the Labor Code on duties when restructuring or changing technology and on labor usage plans.","Current rules on social and unemployment insurance, contribution rates and contribution periods.","Decree 12/2022/ND-CP on administrative penalties in labor and social insurance."]},tools:["Hệ thống quản lý hồ sơ nhân sự","Cơ sở dữ liệu văn bản pháp luật lao động","Bảng tính trợ cấp & quyền lợi","Bộ biểu mẫu hợp đồng, quyết định chuẩn","Phần mềm lưu vết phê duyệt"],kpis:{vi:["Số tranh chấp lao động phát sinh do sai trình tự, thủ tục (mục tiêu 0).","Tỷ lệ hợp đồng lao động đúng loại, đúng hạn ký lại.","Tỷ lệ khoản trợ cấp, quyền lợi tính đúng ngay lần đầu.","Số kết luận vi phạm từ thanh tra lao động (mục tiêu 0)."],en:["Labor disputes caused by procedural errors (target zero).","Share of labor contracts of the right type and renewed on time.","Share of allowances and entitlements calculated right first time.","Violations found by labor inspections (target zero)."]},day:[{time:"08:00",vi:"Rà danh sách hợp đồng sắp hết hạn trong 30 ngày và đề xuất loại hợp đồng tiếp theo.",en:"Review contracts expiring within 30 days and propose the next contract type."},{time:"10:00",vi:"Tư vấn một vụ kỷ luật: kiểm tra chứng cứ, nội quy và trình tự họp xử lý.",en:"Advise on a disciplinary case: check evidence, work rules and hearing procedure."},{time:"13:30",vi:"Tính trợ cấp thôi việc, ngày phép chưa nghỉ cho các trường hợp nghỉ việc trong tháng.",en:"Calculate severance and unused leave pay for this month's leavers."},{time:"15:30",vi:"Họp với công đoàn về phương án sử dụng lao động khi sắp xếp lại chuyền may.",en:"Meet the union on the labor usage plan for reorganizing sewing lines."},{time:"17:00",vi:"Cập nhật sổ theo dõi rủi ro pháp lý lao động và báo cáo ban giám đốc.",en:"Update the employment legal risk log and report to management."}],mistakes:{vi:["Ký hợp đồng xác định thời hạn lần thứ ba cho người lao động không thuộc trường hợp ngoại lệ.","Tính trợ cấp thôi việc trên toàn bộ thời gian làm việc mà không trừ thời gian tham gia bảo hiểm thất nghiệp.","Ép người lao động ký đơn nghỉ việc tự nguyện để né trợ cấp và thủ tục cắt giảm."],en:["Signing a third fixed-term contract with an employee who falls under no exception.","Calculating severance on total service without excluding unemployment insurance years.","Forcing workers to sign voluntary resignations to avoid allowances and layoff procedures."]},career:[{vi:"Chuyên viên quan hệ lao động",en:"Employee relations officer"},{vi:"Chuyên viên pháp lý lao động",en:"Employment law specialist"},{vi:"Trưởng nhóm pháp chế nhân sự",en:"Employment legal team lead"},{vi:"Giám đốc Quan hệ lao động & Pháp chế nhân sự",en:"Director of labor relations & employment law"}],glossary:[{term:"Hợp đồng không xác định thời hạn",vi:"Hợp đồng lao động mà hai bên không xác định thời hạn, thời điểm chấm dứt hiệu lực.",en:"Indefinite-term contract: a labor contract with no fixed duration or end date."},{term:"Trợ cấp thôi việc",vi:"Khoản người sử dụng lao động trả khi hợp đồng chấm dứt trong một số trường hợp, mỗi năm làm việc nửa tháng lương.",en:"Severance allowance: paid on certain terminations, half a month's salary per qualifying year."},{term:"Trợ cấp mất việc làm",vi:"Khoản trả khi cho thôi việc do thay đổi cơ cấu, công nghệ, lý do kinh tế, mỗi năm một tháng lương.",en:"Job-loss allowance: paid on dismissal for restructuring, technology or economic reasons, one month per year."},{term:"Phương án sử dụng lao động",vi:"Kế hoạch bắt buộc khi tái cơ cấu ảnh hưởng nhiều người lao động: danh sách, đào tạo lại, chuyển đổi, chi trả.",en:"Labor usage plan: a mandatory plan for restructuring affecting many workers, covering lists, retraining, transfers and payments."},{term:"Thỏa ước lao động tập thể",vi:"Văn bản thỏa thuận giữa tập thể lao động và người sử dụng lao động về điều kiện lao động.",en:"Collective bargaining agreement: a written deal between the workforce and the employer on working conditions."}],quiz:[{q:{vi:"Người lao động làm việc 10 năm, 6 năm đã tham gia bảo hiểm thất nghiệp, lương bình quân 6 tháng 12000 nghìn đồng. Trợ cấp thôi việc là bao nhiêu?",en:"An employee worked 10 years, 6 of them under unemployment insurance, with a 6-month average salary of 12000 thousand VND. What is the severance?"},options:{vi:["60000 nghìn đồng","36000 nghìn đồng","24000 nghìn đồng","12000 nghìn đồng"],en:["60000 thousand VND","36000 thousand VND","24000 thousand VND","12000 thousand VND"]},answer:2,explain:{vi:"(10 - 6) x 1/2 x 12000 = 24000 nghìn đồng.",en:"(10 - 6) x 1/2 x 12000 = 24000 thousand VND."}},{q:{vi:"Sau khi đã ký hai hợp đồng xác định thời hạn, người lao động bình thường tiếp tục làm việc. Phải ký loại hợp đồng nào?",en:"After two fixed-term contracts, an ordinary employee keeps working. Which contract must be signed?"},options:{vi:["Hợp đồng không xác định thời hạn","Hợp đồng xác định thời hạn 36 tháng","Hợp đồng thử việc mới","Hợp đồng dịch vụ"],en:["Indefinite-term contract","36-month fixed-term contract","A new probation contract","A service contract"]},answer:0,explain:{vi:"Điều 20 Bộ luật Lao động 2019 chỉ cho ký thêm một lần hợp đồng xác định thời hạn, trừ một số trường hợp đặc biệt.",en:"Article 20 of the Labor Code 2019 allows only one more fixed-term contract, except in special cases."}},{q:{vi:"Lãnh đạo yêu cầu soạn sẵn đơn xin nghỉ việc để công nhân ký nhằm né trợ cấp. Bạn làm gì?",en:"Management asks you to pre-write resignation letters for workers to sign to avoid allowances. What do you do?"},options:{vi:["Soạn đơn nhưng để công nhân tự ký","Soạn đơn nếu có thưởng nhỏ cho công nhân","Chỉ soạn cho người mới vào làm","Từ chối, báo lãnh đạo cao hơn và đề xuất quy trình cắt giảm hợp pháp"],en:["Write them but let workers sign themselves","Write them if workers get a small bonus","Only write them for new hires","Refuse, escalate and propose the lawful layoff process"]},answer:3,explain:{vi:"Ép ký đơn tự nguyện là né nghĩa vụ pháp lý, dễ bị tuyên trái luật và bồi thường.",en:"Forced voluntary resignations evade legal duties and are likely to be ruled unlawful with compensation."}},{q:{vi:"Trợ cấp mất việc làm khi cho thôi việc do thay đổi cơ cấu, công nghệ được tính thế nào?",en:"How is the job-loss allowance calculated for dismissal due to restructuring or technology change?"},options:{vi:["Nửa tháng lương mỗi năm","Một tháng lương mỗi năm, ít nhất bằng 2 tháng lương","Ba tháng lương cố định","Không phải trả"],en:["Half a month per year","One month per year, at least 2 months' salary","A fixed 3 months' salary","Nothing is payable"]},answer:1,explain:{vi:"Điều 47 Bộ luật Lao động 2019: mỗi năm làm việc trả 01 tháng tiền lương nhưng ít nhất bằng 02 tháng tiền lương.",en:"Article 47 of the Labor Code 2019: one month's salary per year of work, at least two months' salary."}}],tools_en:["HR records management system","Labor law database","Allowance & benefits spreadsheet","Standard contract and decision templates","Approval audit trail software"]}}})})(window.KKR);
